def prims_algorithm(matrix: List[List[int]]) -> List[Tuple[int, int, int]]:
    num_vertices = len(matrix)
    in_mst = [False] * num_vertices
    edge_weights = [float('inf')] * num_vertices
    parent = [-1] * num_vertices
    edge_weights[0] = 0

    for _ in range(num_vertices):
        min_weight = float('inf')
        u = -1

        for v in range(num_vertices):
            if not in_mst[v] and edge_weights[v] < min_weight:
                min_weight = edge_weights[v]
                u = v

        in_mst[u] = True

        for v in range(num_vertices):
            if matrix[u][v] > 0 and not in_mst[v] and matrix[u][v] < edge_weights[v]:
                edge_weights[v] = matrix[u][v]
                parent[v] = u

    mst_edges = []
    for i in range(1, num_vertices):
        if parent[i] != -1:
            mst_edges.append((parent[i], i, matrix[i][parent[i]]))

    return mst_edges

