def one_edit_away(s1: str, s2: str) -> str:
    if abs(len(s1) - len(s2)) > 1:
        return "No"

    if len(s1) == len(s2):
        # Check if one replacement can make the strings equal
        found_difference = False
        for ch1, ch2 in zip(s1, s2):
            if ch1 != ch2:
                if found_difference:
                    return "No"
                found_difference = True
        return "Yes"

    if len(s1) + 1 == len(s2):
        # Check if inserting one character in s1 can make it equal to s2
        i = j = 0
        while i < len(s1) and j < len(s2):
            if s1[i] != s2[j]:
                if i != j:
                    return "No"
                j += 1
            else:
                i += 1
                j += 1
        return "Yes"

    if len(s1) - 1 == len(s2):
        # Check if removing one character from s1 can make it equal to s2
        i = j = 0
        while i < len(s1) and j < len(s2):
            if s1[i] != s2[j]:
                if i != j:
                    return "No"
                i += 1
            else:
                i += 1
                j += 1
        return "Yes"

    return "No"

