def max_fulfilled_orders(n, m, stock, orders):
    # Sort stock and orders
    stock.sort()
    orders.sort()

    fulfilled_orders = 0
    stock_index = 0

    for order in orders:
        while stock_index < n and stock[stock_index] < order:
            stock_index += 1
        if stock_index < n:
            fulfilled_orders += 1
            stock[stock_index] -= order
            if stock[stock_index] == 0:
                stock_index += 1

    return fulfilled_orders

