import heapq

def max_broadcast(n, m, T, edges):
    # Create a graph from the given edges
    graph = {i: [] for i in range(1, n + 1)}
    for u, v, t in edges:
        graph[u].append((v, t))

    # Dijkstra's algorithm to find the shortest paths from node 1
    distances = {i: float('inf') for i in range(1, n + 1)}
    distances[1] = 0
    priority_queue = [(0, 1)]  # (distance, node)
    heapq.heapify(priority_queue)

    while priority_queue:
        curr_distance, u = heapq.heappop(priority_queue)

        if curr_distance > distances[u]:
            continue

        for v, travel_time in graph[u]:
            distance = curr_distance + travel_time
            if distance < distances[v]:
                distances[v] = distance
                heapq.heappush(priority_queue, (distance, v))

    # Find all nodes that are reachable within time T
    reachable_nodes = [1]
    for i in range(2, n + 1):
        if distances[i] <= T:
            reachable_nodes.append(i)

    return len(reachable_nodes), reachable_nodes

