def max_sum_of_tasks(arr, d):
    """
    Returns the maximum sum of costs of two distinct tasks such that their indices have an absolute difference >= d.
    """
    n = len(arr)
    if n < 2 or d >= n:
        return -1

    max_task_cost = -1
    for i in range(n):
        for j in range(i + d, n):
            max_task_cost = max(max_task_cost, arr[i] + arr[j])

    return max_task_cost if max_task_cost != -1 else -1

