def can_fit_packages(T, test_cases):
    results = []
    for i in range(T):
        N, M, boxes, packages = test_cases[i]
        boxes = sorted(boxes, key=lambda x: (max(x), min(x)))
        possible = True

        for package in packages:
            length, width = package
            fit = False
            for box in boxes:
                box_length, box_width = box
                if (length <= box_length and width <= box_width) or (length <= box_width and width <= box_length):
                    fit = True
                    break
            if not fit:
                possible = False
                break

        if possible:
            results.append("Possible")
        else:
            results.append("Not Possible")

    return results

