def num_distinct_paths(n, m, grid):
    """
    Returns the number of distinct paths from the top-left to the bottom-right of the grid avoiding obstacles.
    n: number of rows
    m: number of columns
    grid: 2D list representing the grid where '.' is an empty cell and '#' is an obstacle
    """
    # Create a DP table initialized to 0
    dp = [[0]*m for _ in range(n)]

    # Start position
    if grid[0][0] == '.':
        dp[0][0] = 1
    else:
        return 0

    # Fill the first row
    for col in range(1, m):
        if grid[0][col] == '.':
            dp[0][col] = dp[0][col - 1]

    # Fill the first column
    for row in range(1, n):
        if grid[row][0] == '.':
            dp[row][0] = dp[row - 1][0]

    # Fill the rest of the table
    for row in range(1, n):
        for col in range(1, m):
            if grid[row][col] == '.':
                dp[row][col] = dp[row - 1][col] + dp[row][col - 1]

    return dp[n-1][m-1]

