def ways_to_split(arr):
    n = len(arr)
    if n < 3:
        return 0

    total_ways = 0

    for i in range(1, n-1):
        for j in range(i+1, n):
            left_sum = sum(arr[:i])
            middle_sum = sum(arr[i:j])
            right_sum = sum(arr[j:])

            if left_sum < middle_sum < right_sum:
                total_ways += 1

    return total_ways

