def longest_subarray_with_two_distinct(nums):
    """
    Returns the length of the longest subarray with at most two distinct integers.
    """
    if not nums:
        return 0

    left = 0
    right = 0
    max_len = 0
    count = {}

    while right < len(nums):
        if nums[right] in count:
            count[nums[right]] += 1
        else:
            count[nums[right]] = 1

        while len(count) > 2:
            count[nums[left]] -= 1
            if count[nums[left]] == 0:
                del count[nums[left]]
            left += 1

        max_len = max(max_len, right - left + 1)
        right += 1

    return max_len

