def lexicographically_smallest_string(s):
    """
    Given a string `s` representing a sequence of lowercase English letters, 
    return the lexicographically smallest string possible after applying the 
    given operation any number of times.
    """
    stack = []
    for char in s:
        while stack and stack[-1] > char:
            stack.pop()
        stack.append(char)
    return ''.join(stack)

