def count_merged_intervals(nums1, nums2):
    """
    Merges overlapping intervals and returns the number of merged intervals.
    """
    if not nums1 or not nums2 or len(nums1) != len(nums2):
        return 0

    intervals = sorted([(nums1[i], nums2[i]) for i in range(len(nums1))])
    merged_intervals = []

    for interval in intervals:
        if not merged_intervals or merged_intervals[-1][1] < interval[0]:
            merged_intervals.append(interval)
        else:
            merged_intervals[-1] = (merged_intervals[-1][0], max(merged_intervals[-1][1], interval[1]))

    return len(merged_intervals)

