def findMedianOfSortedArrays(arr1, arr2):
    """
    Finds the median of the two sorted arrays combined.

    Parameters:
    arr1 (list[int]): A sorted list of integers.
    arr2 (list[int]): A sorted list of integers.

    Returns:
    float: The median of the two sorted arrays combined.
    """
    if len(arr1) > len(arr2):
        arr1, arr2 = arr2, arr1

    x, y = len(arr1), len(arr2)

    low, high = 0, x

    while low <= high:
        partitionX = (low + high) // 2
        partitionY = (x + y + 1) // 2 - partitionX

        maxX = float('-inf') if partitionX == 0 else arr1[partitionX - 1]
        minX = float('inf') if partitionX == x else arr1[partitionX]

        maxY = float('-inf') if partitionY == 0 else arr2[partitionY - 1]
        minY = float('inf') if partitionY == y else arr2[partitionY]

        if maxX <= minY and maxY <= minX:
            if (x + y) % 2 == 0:
                return (max(maxX, maxY) + min(minX, minY)) / 2
            else:
                return max(maxX, maxY)
        elif maxX > minY:
            high = partitionX - 1
        else:
            low = partitionX + 1

