    """
    Catalog and retrieve books based on the publication year range.
    """
    catalog = {}

    # Parse book entries
    for i in range(T):
        id = book_entries[i*3]
        title = book_entries[i*3 + 1]
        year = int(book_entries[i*3 + 2])
        if year not in catalog:
            catalog[year] = []
        catalog[year].append(title)

    # Handle queries
    results = []
    for i in range(Q):
        A, B = queries[i]
        books_in_range = []
        for year in range(A, B + 1):
            if year in catalog:
                books_in_range.extend(catalog[year])
        if books_in_range:
            results.append(sorted(books_in_range))
        else:
            results.append("No books found")

    return results

