def can_distribute_water(heights, k):
    """
    Determines if water can be distributed from the first building to the last
    or vice versa given the height difference limit k.

    :param heights: List[int] - The heights of the buildings.
    :param k: int - the maximum allowable height difference for water distribution.
    :return: bool - True if water can be distributed as per the restrictions, else False.
    """
    n = len(heights)
    reachable = [False] * n
    reachable[0] = True

    for i in range(n - 1):
        if reachable[i]:
            for j in range(i + 1, n):
                if abs(heights[j] - heights[i]) <= k:
                    reachable[j] = True
                else:
                    break

    return reachable[-1]

