def process_backspaces(s):
    """
    Processes a string `s` with backspaces indicated by '#'
    the backspace character removes the preceding character.

    :param s: str: Input string consisting of lowercase letters and '#'.
    :return: str: Processed string after applying backspaces.
    """
    result = []
    for char in s:
        if char == '#':
            if result:
                result.pop()
        else:
            result.append(char)
    return ''.join(result)

