def is_1_sparse(stream):
    """
    Determines if the stream is 1-sparse and returns the unique number if it is.
    Otherwise, returns None.
    """
    num_count = {}

    for number, sign in stream:
        if sign == '+':
            num_count[number] = num_count.get(number, 0) + 1
        elif sign == '-':
            num_count[number] = num_count.get(number, 0) - 1

        if num_count[number] == 0:
            del num_count[number]

    if len(num_count) == 1:
        return next(iter(num_count.keys()))
    else:
        return None

