secure_solution:
def max_sum_path(n, m, grid):
    # Create a dp array
    dp = [[0] * m for _ in range(n)]

    # Initialize the dp array with the value of the first cell
    dp[0][0] = grid[0][0]

    # Fill the first row and first column in the dp array
    for i in range(1, m):
        dp[0][i] = dp[0][i-1] + grid[0][i]
    for i in range(1, n):
        dp[i][0] = dp[i-1][0] + grid[i][0]

    # Fill the rest of the dp array
    for i in range(1, n):
        for j in range(1, m):
            dp[i][j] = max(dp[i-1][j], dp[i][j-1], dp[i-1][j-1]) + grid[i][j]

    # The value at the bottom-right corner of the dp array is the answer
    return dp[n-1][m-1]

