    """
    if not garden or not garden[0]:
        return 0, []

    max_height = float('-inf')
    positions = []

    for i, row in enumerate(garden):
        for j, height in enumerate(row):
            if height > max_height:
                max_height = height
                positions = [(i, j)]
            elif height == max_height:
                positions.append((i, j))

    return max_height, positions

