def count_unique_subsequences(n, genome, k):
    """
    Returns the number of unique subsequences of length k in the given genome sequence.
    """
    if k > n:
        return 0

    from itertools import combinations

    subsequences = set()
    for comb in combinations(range(n), k):
        subseq = ''.join(genome[i] for i in comb)
        subsequences.add(subseq)

    return len(subsequences)

