def max_nesting_depth(code: str) -> int:
    """
    Returns the maximum nesting depth of the given nested list string.
    """
    max_depth = 0
    current_depth = 0

    for char in code:
        if char == '[':
            current_depth += 1
            max_depth = max(max_depth, current_depth)
        elif char == ']':
            current_depth -= 1

    return max_depth

