def max_increasing_sublists(n, nums):
    """
    This function takes an integer n and a list of integers nums, and returns
    the maximum number of strictly increasing sublists that can be formed.
    """
    if n == 0:
        return 0

    count = 1  # Start with one sublist
    for i in range(1, n):
        if nums[i] <= nums[i - 1]:
            count += 1

    return count

