def can_transform(s1, s2):
    """
    Determines whether s1 can be transformed into s2 by rearranging its
    characters and possibly changing exactly one character.
    """
    if len(s1) != len(s2):
        return "NO"

    if sorted(s1) == sorted(s2):
        return "YES"

    # Create frequency count dictionaries
    freq_s1 = {}
    freq_s2 = {}

    for char in s1:
        if char in freq_s1:
            freq_s1[char] += 1
        else:
            freq_s1[char] = 1

    for char in s2:
        if char in freq_s2:
            freq_s2[char] += 1
        else:
            freq_s2[char] = 1

    # Check the number of different characters
    diff_count = 0
    for char in set(s1 + s2):
        diff_count += abs(freq_s1.get(char, 0) - freq_s2.get(char, 0))

    if diff_count <= 2:
        return "YES"

    return "NO"

