from collections import deque

def min_moves_to_clean_room(room):
    """
    Returns the minimum number of moves the robot needs to clean the room.
    If it is not possible to clean the entire room, return -1.
    """
    m, n = len(room), len(room[0])
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    # Find the initial position of the robot
    initial_pos = None
    for i in range(m):
        for j in range(n):
            if room[i][j] == 2:
                initial_pos = (i, j)
                break
        if initial_pos:
            break

    # Breadth-First Search (BFS) setup
    queue = deque([(initial_pos[0], initial_pos[1], 0)])  # (x, y, moves)
    visited = set()
    visited.add((initial_pos[0], initial_pos[1]))

    while queue:
        x, y, moves = queue.popleft()

        # Check all four directions
        for dx, dy in directions:
            nx, ny = x + dx, y + dy

            if 0 <= nx < m and 0 <= ny < n and (nx, ny) not in visited and room[nx][ny] != 1:
                visited.add((nx, ny))
                queue.append((nx, ny, moves + 1))

    # Check if all cells are visited
    for i in range(m):
        for j in range(n):
            if room[i][j] == 0 and (i, j) not in visited:
                return -1

    return max([moves for x, y, moves in queue]) if queue else moves

