def count_divisible_inversions(arr, k):
    """
    Returns the count of inversions in the array that are divisible by k.

    An inversion is defined as a pair (i, j) such that i < j and arr[i] > arr[j].
    """
    count = 0
    n = len(arr)

    for i in range(n):
        for j in range(i + 1, n):
            if arr[i] > arr[j] and (arr[i] - arr[j]) % k == 0:
                count += 1

    return count

