def longest_subarray_to_sort(arr):
    n = len(arr)
    if n <= 1:
        return n

    start, end = -1, -1

    for i in range(n - 1):
        if arr[i] > arr[i + 1]:
            start = i
            break

    if start == -1:
        return n

    for i in range(n - 1, 0, -1):
        if arr[i] < arr[i - 1]:
            end = i
            break

    subarray_min = float('inf')
    subarray_max = float('-inf')

    for i in range(start, end + 1):
        subarray_min = min(subarray_min, arr[i])
        subarray_max = max(subarray_max, arr[i])

    while start > 0 and arr[start - 1] > subarray_min:
        start -= 1

    while end < n - 1 and arr[end + 1] < subarray_max:
        end += 1

    return end - start + 1

