from collections import deque

def min_moves_to_target(n, m, start, target, obstacles):
    x1, y1 = start
    x2, y2 = target
    grid = [[0 for _ in range(m)] for _ in range(n)]

    for ox, oy in obstacles:
        grid[ox-1][oy-1] = 1  # Mark the obstacle in the grid

    if (x1-1, y1-1) == (x2-1, y2-1):
        return 0

    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    queue = deque([(x1-1, y1-1, 0)])  # (x, y, distance)
    visited = set((x1-1, y1-1))

    while queue:
        x, y, dist = queue.popleft()

        for dir_x, dir_y in directions:
            nx, ny = x + dir_x, y + dir_y

            if nx == x2-1 and ny == y2-1:
                return dist + 1

            if 0 <= nx < n and 0 <= ny < m and grid[nx][ny] == 0 and (nx, ny) not in visited:
                visited.add((nx, ny))
                queue.append((nx, ny, dist + 1))

    return -1

