secure_solution:
def maximize_bookshelf_capacity(n, h, book_specs):
    """
    Returns the maximum height capacity Alice can achieve across all sections.

    :param n: Number of types of books (int)
    :param h: Desired height of each bookshelf section (int)
    :param book_specs: List of tuples, each containing height and quantity of each book type (list of tuples)
    :return: Maximum height capacity (int)
    """
    # dp[height] will be True if we can achieve the height using given book types
    dp = [False] * (h + 1)
    dp[0] = True  # We can achieve height 0 by not using any books.

    # Iterate over each type of book
    for height, quantity in book_specs:
        for i in range(h, -1, -1):
            if dp[i]:
                for k in range(1, quantity + 1):
                    if i + k * height <= h:
                        dp[i + k * height] = True

    # Find maximum height that can be achieved
    for i in range(h, -1, -1):
        if dp[i]:
            return i

    return 0

