def find_pair_with_sum(numbers, target):
    """
    Finds the indices of two elements in the sorted list 'numbers' such that their sum equals 'target'.
    Indices are returned as one-based.
    """
    left = 0
    right = len(numbers) - 1

    while left < right:
        current_sum = numbers[left] + numbers[right]
        if current_sum == target:
            return [left + 1, right + 1]  # converting to one-based index
        elif current_sum < target:
            left += 1
        else:
            right -= 1

    return None  # If no pair is found (though based on constraints, this won't happen)

