def find_two_sum_indices(n, arr, target):
    """
    Given an array of integers, returns the indices of the two numbers such that they add up to a specific target.
    The indices should be output in ascending order. If no such indices exist, output -1.
    """
    value_to_index = {}
    for i in range(n):
        complement = target - arr[i]
        if complement in value_to_index:
            return sorted([value_to_index[complement], i])
        value_to_index[arr[i]] = i
    return -1

