def shortestUniqueSubstring(s):
    """
    Returns the length of the shortest substring that contains at least one of every different letter that appears in s.
    """
    unique_chars = set(s)
    required_char_count = len(unique_chars)

    left = 0
    min_length = float('inf')
    char_frequency = {}
    num_unique_found = 0

    for right in range(len(s)):
        if s[right] not in char_frequency:
            char_frequency[s[right]] = 0
        char_frequency[s[right]] += 1

        if char_frequency[s[right]] == 1:
            num_unique_found += 1

        while num_unique_found == required_char_count:
            min_length = min(min_length, right - left + 1)
            char_frequency[s[left]] -= 1
            if char_frequency[s[left]] == 0:
                num_unique_found -= 1
            left += 1

    return min_length

