def min_operations_to_uniform_grid(grid):
    """
    This function returns the minimum number of operations to make all grid values equal,
    or -1 if it is not possible.
    """
    n = len(grid)

    # Check if grid is empty
    if n == 0 or len(grid[0]) == 0:
        return -1

    target = grid[0][0]

    # Check if all values in the grid are already the same
    for row in grid:
        for value in row:
            if value != target:
                return -1

    return 0

