def min_sensors_to_cover(n, m, ranges):
    ranges.sort()  # Sort ranges by their starting point
    end, farthest, sensors, i = 0, 0, 0, 0

    while end < m:
        while i < n and ranges[i][0] <= end + 1:
            farthest = max(farthest, ranges[i][1])
            i += 1

        if end == farthest:
            return -1

        end = farthest
        sensors += 1

    return sensors

