def find_winners(N, T, rates, times):
    winners = []

    for time in times:
        max_problems = -1
        winner_index = -1

        for i in range(N):
            problems_solved = rates[i] * time

            if problems_solved > max_problems:
                max_problems = problems_solved
                winner_index = i + 1  # 1-based index

        winners.append(winner_index)

    return winners

