def check_dominant_trees(n, heights):
    """
    Determines whether each tree in the array is dominant based on its height.

    Parameters:
    n (int): The number of trees.
    heights (list of int): The heights of the trees.

    Returns:
    list of str: A list of strings, each being "DOMINANT" or "NOT DOMINANT".
    """
    results = []

    for i in range(n):
        if i == 0:
            # First tree
            if n == 1 or heights[i] > heights[i + 1]:
                results.append("DOMINANT")
            else:
                results.append("NOT DOMINANT")
        elif i == n - 1:
            # Last tree
            if heights[i] > heights[i - 1]:
                results.append("DOMINANT")
            else:
                results.append("NOT DOMINANT")
        else:
            # Middle trees
            if heights[i] > heights[i - 1] and heights[i] > heights[i + 1]:
                results.append("DOMINANT")
            else:
                results.append("NOT DOMINANT")

    return results

