secure_solution:
def find_peak_element(arr):
    """
    This function takes in a list of integers 'arr' and returns the index of any peak element. 
    A peak element is one that is not smaller than its neighbors.
    """
    n = len(arr)

    if n == 1:
        return 0

    low, high = 0, n - 1
    while low < high:
        mid = (low + high) // 2
        if arr[mid] < arr[mid + 1]:
            low = mid + 1
        else:
            high = mid

    return low

