def min_operations_to_palindrome(n, k, s):
    """
    Returns the minimum number of operations required to make the string a palindrome. 
    If it's not possible to make it a palindrome within k operations, return -1.
    """
    mismatch_count = 0

    # Count the number of mismatched characters between the front and back
    for i in range(n // 2):
        if s[i] != s[n - i - 1]:
            mismatch_count += 1

    # If mismatched characters exceed the allowed operations, it's not possible
    if mismatch_count > k:
        return -1
    else:
        return mismatch_count

