def closest_pair(songs: List[int], target: int) -> Tuple[int, int]:
    songs.sort()
    closest_sum = float('inf')
    closest_pair = (0, 0)
    left, right = 0, len(songs) - 1

    while left < right:
        current_sum = songs[left] + songs[right]
        if abs(target - current_sum) < abs(target - closest_sum):
            closest_sum = current_sum
            closest_pair = (songs[left], songs[right])

        if current_sum == target:
