def count_low_high_pairs(arr):
    """
    Returns the count of low-high pairs in the given array.

    A pair (i, j) is defined as low-high if i < j and arr[i] < arr[j].
    """
    n = len(arr)
    count = 0
    for i in range(n - 1):
        for j in range(i + 1, n):
            if arr[i] < arr[j]:
                count += 1
    return count

