def min_length_after_operations(n, s):
    """
    Returns the minimum possible length of the string after performing any number of operations where
    adjacent different characters can be removed.
    """
    stack = []

    for char in s:
        if stack and stack[-1] != char:
            stack.pop()
        else:
            stack.append(char)

    return len(stack)

