def find_pair_with_sum_sorted(nums, target):
    # Create a list of tuples where each tuple contains a number and its index in the original array
    indexed_nums = list(enumerate(nums))

    # Sort the list of tuples based on the numbers
    indexed_nums.sort(key=lambda x: x[1])

    # Use two pointers to find the two numbers that sum up to the target
    left, right = 0, len(indexed_nums) - 1

    while left < right:
        current_sum = indexed_nums[left][1] + indexed_nums[right][1]
        if current_sum == target:
            return (indexed_nums[left][0], indexed_nums[right][0])
        elif current_sum < target:
            left += 1
        else:
            right -= 1

    return None

