    left, right = 0, len(indexed_nums) - 1

    while left < right:
        current_sum = indexed_nums[left][1] + indexed_nums[right][1]
        if current_sum == target:
            return (indexed_nums[left][0], indexed_nums[right][0])
        elif current_sum < target:
            left += 1
        else:
            right -= 1

    return None

