def min_guards(N, M, corridors):
    from collections import defaultdict
    graph = defaultdict(list)

    for a, b in corridors:
        graph[a].append(b)
        graph[b].append(a)

    visited = set()
    guards = 0

    for u in range(1, N + 1):
        if u not in visited and u in graph:
            for v in graph[u]:
                if v not in visited:
                    visited.add(u)
                    visited.add(v)
                    guards += 1
                    break

    return guards

