def calculate_net_balances(transactions):
    """
    Calculate the net balances of individuals involved in the transactions.

    Parameters:
    transactions (list of tuples): A list of transactions where each transaction is 
                                    represented as a tuple (sender, receiver, amount).

    Returns:
    dict: A dictionary where keys are individuals and values are their respective net balances.
    """
    balance_dict = {}

    for sender, receiver, amount in transactions:
        # Update the sender's balance
        if sender in balance_dict:
            balance_dict[sender] -= amount
        else:
            balance_dict[sender] = -amount

        # Update the receiver's balance
        if receiver in balance_dict:
            balance_dict[receiver] += amount
        else:
            balance_dict[receiver] = amount

    # Remove individuals with a net balance of zero
    net_balances = {person: balance for person, balance in balance_dict.items() if balance != 0}

    return net_balances

