def is_complete_binary_tree(arr):
    """Return true if the input level order traversal list represents a complete binary tree, else false."""
    n = len(arr)

    if n == 0:
        return True

    # A complete binary tree can have null values at the end, but not between nodes
    # Traverse the list, stopping if we get a null and ensuring no node appears after a null

    end_of_tree_found = False

    for i in range(n):
        if arr[i] is None:
            end_of_tree_found = True
        elif end_of_tree_found:
            return False

    return True

