def partition_labels(s):
    """
    Return the starting and ending indices of the smallest number of non-overlapping 
    substrings such that each letter appears in at most one substring.
    """
    if not s:
        return []

    last_occurrence = {char: idx for idx, char in enumerate(s)}
    partitions = []
    start, end = 0, 0

    for idx, char in enumerate(s):
        end = max(end, last_occurrence[char])
        if idx == end:
            partitions.append((start, end))
            start = idx + 1

    return partitions

