def max_product_of_two(arr):
    """
    Returns the maximum possible product of two different elements in the array.
    """
    if len(arr) < 2:
        raise ValueError("Array must contain at least 2 elements")

    # Initialize the largest and second largest values to the smallest possible
    largest = float('-inf')
    second_largest = float('-inf')

    # Initialize the smallest and second smallest values to the largest possible
    smallest = float('inf')
    second_smallest = float('inf')

    # Traverse the array and find the largest, second largest, and smallest, second smallest
    for num in arr:
        if num > largest:
            second_largest = largest
            largest = num
        elif num > second_largest:
            second_largest = num

        if num < smallest:
            second_smallest = smallest
            smallest = num
        elif num < second_smallest:
            second_smallest = num

    # The maximum product could be either from the two largest or the two smallest (if they are both negative)
    return max(largest * second_largest, smallest * second_smallest)

