def most_frequent_substring(s: str, length: int) -> str:
    if length == 0 or not s or length > len(s):
        return ""

    substring_count = {}

    # Slide over the string to count all substrings of the given length
    for i in range(len(s) - length + 1):
        substring = s[i:i+length]
        if substring in substring_count:
            substring_count[substring] += 1
        else:
            substring_count[substring] = 1

    # Find the most frequent substring
    max_frequency = max(substring_count.values())
    most_frequent = [substr for substr, count in substring_count.items() if count == max_frequency]

    # Return the lexicographically smallest substring if there's a tie
    return min(most_frequent)

