def exists_subgrid_with_avg_beauty(n, m, alpha, grid):
    prefix_sum = [[0] * (m + 1) for _ in range(n + 1)]

    for i in range(1, n + 1):
        for j in range(1, m + 1):
            prefix_sum[i][j] = (grid[i - 1][j - 1] + prefix_sum[i - 1][j] + prefix_sum[i][j - 1] 
                                - prefix_sum[i - 1][j - 1])

    for top in range(n):
        for bottom in range(top, n):
            for left in range(m):
                for right in range(left, m):
                    total_elements = (bottom - top + 1) * (right - left + 1)
                    total_sum = (prefix_sum[bottom + 1][right + 1] 
                                - prefix_sum[top][right + 1] 
                                - prefix_sum[bottom + 1][left] 
                                + prefix_sum[top][left])

                    if total_sum / total_elements >= alpha:
                        return "YES"

    return "NO"

