def balance_and_calculate_score(s):
    stack = []
    score_stack = [0]

    for char in s:
        if char == '(':
            stack.append(char)
            score_stack.append(0)
        elif char == ')':
            if not stack:
                return "Invalid"
            stack.pop()
            last_score = score_stack.pop()
            score_stack[-1] += max(2 * last_score, 1)

    if stack:
        return "Invalid"

    return score_stack[-1]

