def countPaths(n, m, k, traps):
    MOD = 1000000007

    trap_set = {(r, c) for r, c in traps}

    if (n, m) in trap_set or (1, 1) in trap_set:
        return 0

    dp = [[0] * (m + 1) for _ in range(n + 1)]
    dp[1][1] = 1

    for i in range(1, n + 1):
        for j in range(1, m + 1):
            if (i, j) in trap_set:
                dp[i][j] = 0
            else:
                if i > 1:
                    dp[i][j] = (dp[i][j] + dp[i - 1][j]) % MOD
                if j > 1:
                    dp[i][j] = (dp[i][j] + dp[i][j - 1]) % MOD

    return dp[n][m]

