        color = nums[right]
        if color_count[color] == 0:
            distinct_colors += 1
        color_count[color] += 1

        while distinct_colors > k:
            left_color = nums[left]
            color_count[left_color] -= 1
            if color_count[left_color] == 0:
                distinct_colors -= 1
            left += 1

        if distinct_colors == k:
            max_length = max(max_length, right - left + 1)

    return max_length

