def max_length_subarray_with_sum(arr, k):
    n = len(arr)
    # Initialize variables
    current_sum = 0
    max_len = 0
    start_index = 0

    # Dictionary to store the first occurrence of a particular prefix sum
    prefix_sum = {}

    left = 0
    right = -1

    for i in range(n):
        current_sum += arr[i]

        if current_sum == k:
            max_len = i + 1
            left = 0
            right = i

        if (current_sum - k) in prefix_sum:
            if max_len < i - prefix_sum[current_sum - k]:
                max_len = i - prefix_sum[current_sum - k]
                left = prefix_sum[current_sum - k] + 1
                right = i

        if current_sum not in prefix_sum:
            prefix_sum[current_sum] = i

    if max_len == 0:
        return -1
    return left + 1, right + 1

