def find_shortest_word(s):
    """
    Returns the shortest word from the input string. If there are multiple words with the same length, 
    returns the first one that appears.
    """
    words = s.split()
    if not words:
        return ""
    shortest_word = words[0]
    for word in words[1:]:
        if len(word) < len(shortest_word):
            shortest_word = word
    return shortest_word

