def replace_phrases_with_abbreviations(n, phrases, m, sentences):
    from collections import defaultdict, Counter

    # Create a dictionary of the phrase to abbreviation mappings
    phrase_to_abbr = {}
    for phrase, abbr in phrases:
        phrase_to_abbr[phrase] = abbr

    # Calculate the frequency of each phrase in the sentences
    phrase_freq = Counter()
    for sentence in sentences:
        for phrase in phrase_to_abbr.keys():
            if phrase in sentence:
                phrase_freq[phrase] += sentence.count(phrase)

    # Sort phrases by frequency, then by length, then lexicographically
    sorted_phrases = sorted(phrase_to_abbr.keys(), key=lambda p: (-phrase_freq[p], len(p), p))

    # Replace the phrases with abbreviations in the sentences
    result = []
    for sentence in sentences:
        for phrase in sorted_phrases:
            sentence = sentence.replace(phrase, phrase_to_abbr[phrase])
        result.append(sentence)

    return result

