def find_indices_with_closest_sum_to_zero(n, arr):
    """
    Finds two indices i and j (1-based indexing) such that the sum of the elements at these indices is closest to zero.
    """
    closest_sum = float('inf')
    closest_pair = (0, 0)

    for i in range(n):
        for j in range(i + 1, n):
            current_sum = arr[i] + arr[j]
            if abs(current_sum) < abs(closest_sum) or (abs(current_sum) == abs(closest_sum) and (i + 1 < closest_pair[0] or (i + 1 == closest_pair[0] and j + 1 < closest_pair[1]))):
                closest_sum = current_sum
                closest_pair = (i + 1, j + 1)

    return closest_pair

