def find_unique_pairs(arr, target):
    """
    Returns the number of unique pairs in the array that sum up to the target value.
    """
    seen = set()
    pair_set = set()

    for number in arr:
        complement = target - number
        if complement in seen:
            pair = tuple(sorted((number, complement)))
            pair_set.add(pair)
        seen.add(number)

    return len(pair_set)

