def lexicographically_smallest_string(s):
    """
    Returns the lexicographically smallest string possible after performing 
    any number of allowed operations i.e., swapping or removing adjacent 
    similar characters.
    """
    stack = []

    for char in s:
        if stack and stack[-1] == char:
            stack.pop()
        else:
            stack.append(char)

    return "".join(stack)

