def four_sum_indices(arr, target):
    length = len(arr)
    if length < 4:
        return []

    # Dictionary to keep track of pairs and indices
    pairs = {}
    for i in range(length - 1):
        for j in range(i + 1):
            current_sum = arr[i] + arr[j]
            if current_sum not in pairs:
                pairs[current_sum] = []
            pairs[current_sum].append((i, j))

