def min_lex_order(n, s, k):
    """
    Returns the minimum length of the lexicographically ordered string 
    after deleting exactly k characters from the input string s.
    """
    result = []
    for char in s:
        while k and result and result[-1] > char:
            result.pop()
            k -= 1
        result.append(char)

    return ''.join(result[:n - k])

