def surface_area(grid):
    rows = len(grid)
    cols = len(grid[0])
    area = 0

    for i in range(rows):
        for j in range(cols):
            if grid[i][j] > 0:
                area += 2  # top and bottom surface area
                # Add sides area while considering adjacent height difference
                area += grid[i][j]  # front
                area += grid[i][j]  # back
                area += grid[i][j]  # left
                area += grid[i][j]  # right

                if i > 0:
                    area -= min(grid[i][j], grid[i-1][j])  # overlap with the block above
                if i < rows - 1:
                    area -= min(grid[i][j], grid[i+1][j])  # overlap with the block below
                if j > 0:
                    area -= min(grid[i][j], grid[i][j-1])  # overlap with the block to the left
                if j < cols - 1:
                    area -= min(grid[i][j], grid[i][j+1])  # overlap with the block to the right

    return area

