def smallest_absent_integer(N, A, K, operations):
    # Step 1: Apply the operations to the list A and generate the final list B
    B = A[:]

    for L, R, X in operations:
        for j in range(L-1, R):
            B[j] += X

    # Step 2: Find the smallest non-present integer in B
    B_set = set(B)
    C = 1
    while C in B_set:
        C += 1

    return C

