def largest_number_from_matches(matches):
    """
    Find the largest possible number that can be formed using exactly the given amount of matches.

    :param matches: Number of matches available
    :return: The largest number represented as a string that can be formed with the matches
    """
    # Digit to matches mapping
    digit_to_matches = [6, 2, 5, 5, 4, 5, 6, 3, 7, 6]

    if matches == 2:
        return "1"

    num_digits = matches // 2
    if matches % 2 == 0:
        return '1' * num_digits
    else:
        return '7' + '1' * (num_digits - 1)

