def can_organize_books(T, test_cases):
    results = []

    for i in range(T):
        N, K, M = test_cases[i][0]
        pages = test_cases[i][1]

        if max(pages) > M:
            results.append("NO")
            continue

        current_sum = 0
        shelves = 1

        for page in pages:
            if current_sum + page > M:
                shelves += 1
                current_sum = page
                if shelves > K:
                    break
            else:
                current_sum += page

        if shelves <= K:
            results.append("YES")
        else:
            results.append("NO")

    return results

