        pages = test_cases[i][1]

        if max(pages) > M:
            results.append("NO")
            continue

        current_sum = 0
        shelves = 1

        for page in pages:
            if current_sum + page > M:
                shelves += 1
                current_sum = page
                if shelves > K:
