def longest_palindromic_subsequence(arr):
    n = len(arr)
    dp = [[0] * n for _ in range(n)]

    for i in range(n):
        dp[i][i] = 1

    for cl in range(2, n+1):
        for i in range(n - cl + 1):
            j = i + cl - 1
            if arr[i] == arr[j] and cl == 2:
                dp[i][j] = 2
            elif arr[i] == arr[j]:
                dp[i][j] = dp[i+1][j-1] + 2
            else:
                dp[i][j] = max(dp[i][j-1], dp[i+1][j])

    return dp[0][n-1]

