def multiply(multiplicand: list[list[int]], multiplier: list[list[int]]) -> list[list[int]]:
    # Get the dimensions of the matrices
    m = len(multiplicand)
    n = len(multiplicand[0])
    p = len(multiplier[0])

    # Ensure the matrices can be multiplied
    if len(multiplier) != n:
        raise ValueError("Incompatible matrices for multiplication")

    # Initialize the product matrix with zeros
    product = [[0 for _ in range(p)] for _ in range(m)]

    # Perform matrix multiplication
    for i in range(m):
        for j in range(p):
            for k in range(n):
                product[i][j] += multiplicand[i][k] * multiplier[k][j]

    return product

import heapq

def trap_rain_water(n, height):
    if n <= 2:
        return 0

    trapped_water = 0
    visited = [[False] * n for _ in range(n)]
    min_heap = []

    for i in range(n):
        for j in range(n):
            if i == 0 or i == n-1 or j == 0 or j == n-1:
                heapq.heappush(min_heap, (height[i][j], i, j))
                visited[i][j] = True

    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    while min_heap:
        h, x, y = heapq.heappop(min_heap)
        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < n and 0 <= ny < n and not visited[nx][ny]:
                trapped_water += max(0, h - height[nx][ny])
                heapq.heappush(min_heap, (max(h, height[nx][ny]), nx, ny))
                visited[nx][ny] = True

    return trapped_water

