def find_zero_sum_pairs(arr):
    """
    Returns a list of unique pairs that add up to zero.
    Each inner pair should have the smaller number first.
    """
    seen = set()
    result = []

    for num in arr:
        target = -num
        if target in seen:
            pair = sorted([target, num])
            if pair not in result:
                result.append(pair)
        else:
            seen.add(num)

    return result

