import heapq

def process_operations(operations):
    """
    Process a sequence of operations on a min-heap.

    :param operations: A list of strings representing the operations.
    :return: A list of results for "remove" and "min" operations.
    """
    min_heap = []
    results = []

    for operation in operations:
        if operation.startswith("insert"):
            _, x = operation.split()
            heapq.heappush(min_heap, int(x))
        elif operation == "remove":
            if min_heap:
                smallest = heapq.heappop(min_heap)
                results.append(smallest)
            else:
                results.append("Heap is empty")
        elif operation == "min":
            if min_heap:
                smallest = min_heap[0]
                results.append(smallest)
            else:
                results.append("Heap is empty")

    return results

