def calculate_payable_amount(prices):
    """
    Returns the total amount payable after applying discounts based on the number of unique items.
    """
    # Calculate the total bill
    total_bill = sum(prices)

    # Get the number of unique items
    unique_items_count = len(set(prices))

    # Determine the discount percentage
    if unique_items_count >= 7:
        discount = 0.15
    elif unique_items_count >= 5:
        discount = 0.10
    elif unique_items_count >= 3:
        discount = 0.05
    else:
        discount = 0.0

    # Calculate the amount payable after applying the discount
    amount_payable = total_bill * (1 - discount)

    return round(amount_payable, 2)

def count_rectangles(n, m, grid):
    """
    Counts the number of unique rectangles that can be formed using 'X' in the grid.

    :param n: Height of the grid
    :param m: Width of the grid
    :param grid: 2D list representation of the grid
    :return: Number of unique rectangles
    """
    # Find all the coordinates of 'X' in the grid
    x_coordinates = []
    for i in range(n):
        for j in range(m):
            if grid[i][j] == 'X':
                x_coordinates.append((i, j))

    # Use a set to store unique rectangles
    unique_rectangles = set()

    x_count = len(x_coordinates)
    for i in range(x_count):
        for j in range(i + 1, x_count):
            x1, y1 = x_coordinates[i]
            x2, y2 = x_coordinates[j]

            # Check if they can be opposite corners of a rectangle
            if x1 != x2 and y1 != y2:
                if (x1, y2) in x_coordinates and (x2, y1) in x_coordinates:
                    # Represent the rectangle by its sorted coordinates to avoid duplicates
                    rect = tuple(sorted([(x1, y1), (x1, y2), (x2, y1), (x2, y2)]))
                    unique_rectangles.add(rect)

    return len(unique_rectangles)

