def minimal_communication_paths(n, relationships):
    if n == 1:
        return 0

    # Create the adjacency list
    from collections import defaultdict

    managers = defaultdict(list)

    for u, v in relationships:
        managers[u].append(v)

    # The number of paths needed is equivalent to the number of edges
    return n - 1

