def length_of_longest_good_substring(n, s):
    """
    Find the length of the longest substring with at most two distinct characters.

    :param n: Length of string s.
    :param s: Input string.
    :return: Length of the longest "good" substring.
    """
    max_length = 0
    start = 0
    char_count = {}

    for end in range(n):
        if s[end] in char_count:
            char_count[s[end]] += 1
        else:
            char_count[s[end]] = 1

        while len(char_count) > 2:
            char_count[s[start]] -= 1
            if char_count[s[start]] == 0:
                del char_count[s[start]]
            start += 1

        max_length = max(max_length, end - start + 1)

    return max_length

