def can_be_balanced_with_one_swap(n, a):
    even_sum = sum(a[i] for i in range(0, n, 2))
    odd_sum = sum(a[i] for i in range(1, n, 2))

    if even_sum == odd_sum:
        return "YES"

    for i in range(n):
        for j in range(i + 1, n):
            if (i % 2 == 0 and j % 2 == 1) or (i % 2 == 1 and j % 2 == 0):
                new_even_sum = even_sum - a[i] + a[j]
                new_odd_sum = odd_sum - a[j] + a[i]

                if new_even_sum == new_odd_sum:
                    return "YES"

    return "NO"

