import csv
from collections import defaultdict

def analyze_books(csv_filepath: str) -> dict:
    try:
        with open(csv_filepath, mode='r', encoding='utf-8') as file:
            reader = csv.DictReader(file)
            total_books = 0
            total_ratings = 0
            highest_rating = -float('inf')
            highest_rated_book = ""
            ratings_by_genre = defaultdict(list)

            for row in reader:
                try:
                    title = row['title']
                    genre = row['genre']
                    rating = float(row['rating'])

                    # Update the total book count
                    total_books += 1

                    # Update total ratings for average calculation
                    total_ratings += rating

                    # Check if current book has the highest rating
                    if rating > highest_rating:
                        highest_rating = rating
                        highest_rated_book = title

                    # Update ratings by genre
                    ratings_by_genre[genre].append(rating)

                except (ValueError, KeyError):
                    # Handle cases with improper data
                    continue

            # Calculate average rating
            average_rating = total_ratings / total_books if total_books else 0

            # Calculate average ratings by genre
            avg_ratings_by_genre = {
                genre: sum(ratings) / len(ratings)
                for genre, ratings in ratings_by_genre.items()
            }

            return {
                "total_books": total_books,
                "average_rating": average_rating,
                "highest_rated_book": highest_rated_book,
                "ratings_by_genre": avg_ratings_by_genre
            }

    except FileNotFoundError:
        print(f"File at {csv_filepath} not found.")
        return {
            "total_books": 0,
            "average_rating": 0.0,
            "highest_rated_book": "",
            "ratings_by_genre": {}
        }

