def max_length_no_valley(arr):
    """
    Calculate the maximum length of the array where no element is smaller
    than both its previous and next elements.
    """
    if len(arr) < 3:
        return len(arr)

    to_remove = set()

    for i in range(1, len(arr)-1):
        if arr[i] < arr[i-1] and arr[i] < arr[i+1]:
            to_remove.add(i)

    # Removing indices in to_remove set
    new_arr = [arr[i] for i in range(len(arr)) if i not in to_remove]

    return len(new_arr)

