def min_operations(start, target):
    """
    Computes the minimum number of single-character operations needed to transform start into target.
    Allowed operations are insertion, deletion, and substitution.
    """
    m, n = len(start), len(target)

    # Initialize the dynamic programming table
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    # Base cases
    for i in range(m + 1):
        dp[i][0] = i
    for j in range(n + 1):
        dp[0][j] = j

    # Fill the table
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if start[i - 1] == target[j - 1]:
                dp[i][j] = dp[i - 1][j - 1]  # No operation required
            else:
                dp[i][j] = 1 + min(dp[i - 1][j],     # Deletion
                                   dp[i][j - 1],     # Insertion
                                   dp[i - 1][j - 1])  # Substitution

    return dp[m][n]

