import heapq

def task_management(queries):
    tasks = []
    completed_tasks = set()
    result = []

    for query in queries:
        parts = query.split()
        command = parts[0]
        if command == "ADD":
            priority = int(parts[1])
            heapq.heappush(tasks, priority)
        elif command == "COMPLETE":
            priority = int(parts[1])
            completed_tasks.add(priority)
        elif command == "QUERY":
            while tasks and tasks[0] in completed_tasks:
                heapq.heappop(tasks)
            if tasks:
                result.append(tasks[0])
            else:
                result.append("NONE")

    return result

