def minimum_consecutive_sum(N, arr):
    """
    Finds the minimum value among the sum of every two consecutive elements in the array.
    If the array has fewer than 2 elements, return 0.
    """
    if N < 2:
        return 0

    min_sum = float('inf')
    for i in range(N - 1):
        current_sum = arr[i] + arr[i + 1]
        if current_sum < min_sum:
            min_sum = current_sum

    return min_sum

def max_activities(t, test_cases):
    result = []
    for i in range(t):
        n, m, activities = test_cases[i]
        selected_employees = set()
        count = 0

        for u, v in activities:
            if u not in selected_employees and v not in selected_employees:
                selected_employees.add(u)
                selected_employees.add(v)
                count += 1

        result.append(count)

    return result

