def min_groups(strings):
    """
    Returns the minimum number of groups so that no string in one group
    is a prefix of another string in the same group.
    """
    # Sort strings by length, then lexicographically
    strings.sort(key=lambda s: (len(s), s))

    groups = []

    for s in strings:
        placed = False
        for group in groups:
            if not any(g.startswith(s) or s.startswith(g) for g in group):
                group.append(s)
                placed = True
                break
        if not placed:
            groups.append([s])

    return len(groups)

